export const ListMyAttemptsQueryParams = zod.object({
  "page": zod.coerce.number().default(listMyAttemptsQueryPageDefault),
  "limit": zod.coerce.number().default(listMyAttemptsQueryLimitDefault)
})

export const ListMyAttemptsResponse = zod.object({
  "attempts": zod.array(zod.object({
  "sessionId": zod.number(),
  "examTypeName": zod.string(),
  "subjectName": zod.string(),
  "year": zod.number(),
  "score": zod.number(),
  "percentage": zod.number(),
  "passed": zod.boolean(),
  "totalQuestions": zod.number(),
  "correct": zod.number().optional(),
  "submittedAt": zod.coerce.date()
})),
  "total": zod.number(),
  "page": zod.number(),
  "limit": zod.number()
})


/**
 * @summary Get dashboard summary stats (admin)
 */
export const GetDashboardStatsResponse = zod.object({
  "totalUsers": zod.number(),
  "totalQuestions": zod.number(),
  "publishedQuestions": zod.number(),
  "totalAttempts": zod.number(),
  "totalSubjects": zod.number().optional(),
  "totalExamTypes": zod.number().optional(),
  "recentAttempts": zod.array(zod.object({
  "sessionId": zod.number(),
  "examTypeName": zod.string(),
  "subjectName": zod.string(),
  "year": zod.number(),
  "score": zod.number(),
  "percentage": zod.number(),
  "passed": zod.boolean(),
  "totalQuestions": zod.number(),
  "correct": zod.number().optional(),
  "submittedAt": zod.coerce.date()
})).optional()
})


/**
 * @summary Get the current user's progress summary
 */
export const GetMyProgressResponse = zod.object({
  "totalAttempts": zod.number(),
  "averageScore": zod.number(),
  "totalQuestionsAnswered": zod.number(),
  "bestScore": zod.number().nullish(),
  "recentAttempts": zod.array(zod.object({
  "sessionId": zod.number(),
  "examTypeName": zod.string(),
  "subjectName": zod.string(),
  "year": zod.number(),
  "score": zod.number(),
  "percentage": zod.number(),
  "passed": zod.boolean(),
  "totalQuestions": zod.number(),
  "correct": zod.number().optional(),
  "submittedAt": zod.coerce.date()
})).optional(),
  "subjectBreakdown": zod.array(zod.object({
  "subjectId": zod.number(),
  "subjectName": zod.string(),
  "attempts": zod.number(),
  "averageScore": zod.number()
}))
})


